const long long MOD = 1000000007;          // 소수
long long fact[MAXN], inv[MAXN];
fact[0] = 1;
for (int i = 1; i <= N; i++) fact[i] = fact[i-1] * i % MOD;
inv[N] = pw(fact[N], MOD - 2);             // 페르마의 소정리로 역원
for (int i = N; i >= 1; i--) inv[i-1] = inv[i] * i % MOD;
// C(n, r) = fact[n] * inv[r] % MOD * inv[n-r] % MOD

